/*
 * 文件名识别（高亮反推）验证 —— v2.65
 *
 * 背景：高亮要靠文件名反推日期，而文件名格式是用户自己定的。
 * 早期只认 settings.notes[kind].format 一条，且带文件夹的格式
 * （Calendar 那种 gggg/gggg-[W]WW）根本匹配不上 —— 只对我自己的
 * 命名习惯成立，换个人就失效。
 *
 * 现在：
 *   1. 高亮与「打开已有笔记」共用同一份候选清单（配置 + 用户额外 + 常见异名）
 *   2. 设置里给「额外文件名格式」输入框，用户可自己补
 *   3. 纯 token 格式（如年记 YYYY）不放宽后缀，防「2026年度总结」误判
 */
const path = __dirname + '/../src/';
const cal = require(path + 'calendar.js');
const note = require(path + 'note.js');

let failures = 0;
function check(name, cond, extra) {
  if (cond) console.log('  ✓ ' + name);
  else { failures++; console.log('  ✗ ' + name + (extra !== undefined ? ' → ' + extra : '')); }
}

function ref(name, notes, dow) {
  return cal.parseNoteRef(name, dow == null ? 1 : dow, notes);
}
function brief(r) {
  if (!r) return 'null';
  const d = r.date;
  const p = (x) => (x < 10 ? '0' + x : '' + x);
  return r.kind + ' ' + d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate());
}

const DEF = {
  daily: { folder: '', format: 'YYYY-MM-DD', template: '', altFormats: '' },
  weekly: { folder: '', format: 'gggg-[W]ww', template: '', altFormats: '' },
  monthly: { folder: '', format: 'YYYY-MM', template: '', altFormats: '' },
  yearly: { folder: '', format: 'YYYY', template: '', altFormats: '' },
};
const mk = (over) => {
  const o = JSON.parse(JSON.stringify(DEF));
  Object.keys(over || {}).forEach((k) => Object.assign(o[k], over[k]));
  return o;
};

console.log('\n[1] 默认配置');
check('日记 2026-09-22-周二', brief(ref('2026-09-22-周二', DEF)) === 'day 2026-09-22', brief(ref('2026-09-22-周二', DEF)));
check('日记 2026-09-22', brief(ref('2026-09-22', DEF)) === 'day 2026-09-22');
check('周记 2026-W38', brief(ref('2026-W38', DEF)) === 'week 2026-09-14', brief(ref('2026-W38', DEF)));
check('月记 2026-09', brief(ref('2026-09', DEF)) === 'month 2026-09-01', brief(ref('2026-09', DEF)));
check('年记 2026', brief(ref('2026', DEF)) === 'year 2026-01-01', brief(ref('2026', DEF)));
check('普通笔记 2026 年度总结 → null', ref('2026 年度总结', DEF) === null, brief(ref('2026 年度总结', DEF)));
check('普通笔记 月度复盘 → null', ref('月度复盘', DEF) === null);

/*
 * 英文星期后缀（v3.33.0）
 *
 * v3.32.0 起文件名可以输出英文星期（ddd → Tue），所以要确认日历认得回来，
 * 否则会出现「笔记建了、日历上没圆点」。
 *
 * 实测结论：parseNoteRef 里唯一的 \D{0,2} 是**年月日之间的分隔符**，
 * 不是星期后缀匹配器 —— 后缀压根不参与匹配，中英文都直接被忽略。
 * 所以不需要改正则，但这组用例必须留着：哪天有人真去"放宽后缀"，
 * 中文两字能过、英文 3~9 个字母未必能过，这里会立刻报红。
 */
check('英文星期缩写 2026-09-22-Tue', brief(ref('2026-09-22-Tue', DEF)) === 'day 2026-09-22', brief(ref('2026-09-22-Tue', DEF)));
check('英文星期缩写 2026-09-22 Tue', brief(ref('2026-09-22 Tue', DEF)) === 'day 2026-09-22', brief(ref('2026-09-22 Tue', DEF)));
check('英文星期全拼 2026-09-22-Tuesday', brief(ref('2026-09-22-Tuesday', DEF)) === 'day 2026-09-22', brief(ref('2026-09-22-Tuesday', DEF)));
check('英文星期全拼 2026-09-22 Wednesday', brief(ref('2026-09-22 Wednesday', DEF)) === 'day 2026-09-22', brief(ref('2026-09-22 Wednesday', DEF)));

console.log('\n[2] 用户自定义格式（别人用的命名）');
const A = mk({
  daily: { format: 'YYYY年M月D日' },
  weekly: { format: 'YYYY-第ww周' },
  monthly: { format: 'YYYY年M月' },
  yearly: { format: 'YYYY年' },
});
check('2026年9月22日 → day', brief(ref('2026年9月22日', A)) === 'day 2026-09-22', brief(ref('2026年9月22日', A)));
check('2026-第38周 → week', brief(ref('2026-第38周', A)) === 'week 2026-09-14', brief(ref('2026-第38周', A)));
check('2026年9月 → month', brief(ref('2026年9月', A)) === 'month 2026-09-01', brief(ref('2026年9月', A)));
check('2026年 → year', brief(ref('2026年', A)) === 'year 2026-01-01', brief(ref('2026年', A)));
check('2026年度总结 仍 → null（不放宽后缀）', ref('2026年度总结', A) === null, brief(ref('2026年度总结', A)));

console.log('\n[3] 额外文件名格式（设置里的窗口）');
const B = mk({ daily: { altFormats: '日记-YYYY-MM-DD，YYYY.MM.DD' } });
check('日记-2026-09-22 → day', brief(ref('日记-2026-09-22', B)) === 'day 2026-09-22', brief(ref('日记-2026-09-22', B)));
check('2026.09.22 → day', brief(ref('2026.09.22', B)) === 'day 2026-09-22', brief(ref('2026.09.22', B)));
const B2 = mk({ yearly: { altFormats: '年记/YYYY' } });
check('带文件夹 年记/2026 → year', brief(ref('2026', B2)) === 'year 2026-01-01', brief(ref('2026', B2)));

console.log('\n[4] 带文件夹的格式（Calendar 风格）');
const C = mk({ weekly: { format: 'gggg/gggg-[W]WW' } });
check('gggg/gggg-[W]WW → 2026-W38 得 week38', brief(ref('2026-W38', C)) === 'week 2026-09-14', brief(ref('2026-W38', C)));
const C2 = mk({ weekly: { format: 'gggg-WWW' } });
check('gggg-WWW → 2026-W38 得 week38', brief(ref('2026-W38', C2)) === 'week 2026-09-14', brief(ref('2026-W38', C2)));

console.log('\n[5] 周起始日影响周记反推');
check('周日起始 2026-W38 → 09-13', brief(ref('2026-W38', DEF, 0)) === 'week 2026-09-13', brief(ref('2026-W38', DEF, 0)));
check('周一起始 2026-W38 → 09-14', brief(ref('2026-W38', DEF, 1)) === 'week 2026-09-14', brief(ref('2026-W38', DEF, 1)));

console.log('\n[6] 无效输入不臆造');
check('2026-02-30 → null', ref('2026-02-30', DEF) === null, brief(ref('2026-02-30', DEF)));
check('2026-13-01 → null', ref('2026-13-01', DEF) === null);
check('空串 → null', ref('', DEF) === null);
check('无数字 → null', ref('随手记', DEF) === null);

console.log('\n[7] highlightFormats 与打开共用同一清单');
const hl = note.highlightFormats({ notes: mk({ daily: { altFormats: 'X-YYYY-MM-DD' } }) }, 'daily');
check('含配置格式', hl[0] === 'YYYY-MM-DD', hl[0]);
check('含用户额外格式', hl.indexOf('X-YYYY-MM-DD') === 1, hl.join('|'));
check('含内置异名', hl.indexOf('YYYY-MM-DD-ddd') > 0);
check('已去重', new Set(hl).size === hl.length, hl.length);

console.log('\n[8] 白名单不积累废弃键');
const settings = require(path + 'settings.js');
const dirty = settings.migrateSettings({
  timestamp: {}, pomodoro: {}, calendar: {}, record: {},
  notes: { daily: { format: 'YYYY-MM-DD', 废弃键: 1 }, weekly: { format: 'x' } },
});
check('notes.daily.废弃键 已剔除', dirty.notes.daily['废弃键'] === undefined);
check('altFormats 补默认值', dirty.notes.monthly.altFormats === '');
check('保留有效 format', dirty.notes.daily.format === 'YYYY-MM-DD');

console.log('\n' + (failures ? '✗ 失败 ' + failures + ' 项' : '✓ 全部通过'));
process.exit(failures ? 1 : 0);
